// === Tab: mySketch ===
let treeAngleThreshold = 360;
let grassAngleThreshold = 360;

let baseGrassSize = 6;
let isWhiteGrass = false;
let isWhiteWood = false;
let isDarkGrass = true;

let mainHue = 0;

async function setup() {
  createCanvas(windowWidth, windowHeight);
  background(60);
  colorMode(HSB);

  let angleRandom = random();
  if (angleRandom < 0.5) // totally curve
  {
    treeAngleThreshold = 1;
    grassAngleThreshold = 1;
  }
  else if (angleRandom < 0.7) // 30
  {
    treeAngleThreshold = 45;
    grassAngleThreshold = 45;
  }
  else if (angleRandom < 0.9) // grass straight
  {
    treeAngleThreshold = 45;
    grassAngleThreshold = 360;
  }
  else // all straight
  {
    treeAngleThreshold = 360;
    grassAngleThreshold = 360;
  }

  let colorType = floor(random(0, 4));
  if (colorType == 0) {
    isWhiteGrass = true;
    isWhiteWood = false;
  }
  else if (colorType == 1) {
    isWhiteGrass = false;
    isWhiteWood = true;
  }
  else if (colorType == 2) {
    isWhiteGrass = false;
    isWhiteWood = false;
  }
  else if (colorType == 3) {
    isWhiteGrass = true;
    isWhiteWood = true;
  }

  mainHue = random(0, 360);
  baseGrassSize = random(20, 40);
  isDarkGrass = random() < 0.5;

  for (let y = -100; y < height; y += 3) {
    let xPos = 0;
    let yPos = 0;
    let rectSize = 0;
    let startRot = 0;

    for (let x = -100; x < width + 100; x += 12) {

      xPos = x + random(-3, 3);
      yPos = y + noise(x * 0.003, y * 0.01) * 200;
      rectSize = noise(x * 0.01, y * 0.01) * baseGrassSize;
      startRot = noise(x * 0.01, y * 0.01) * 80 - 40;

      let drawCount = floor(random(6, 20));
      // rect(xPos, yPos, rectSize, rectSize);
      drawGrass(xPos, yPos, rectSize, drawCount, startRot);
    }

    if (random() < 0.06 && y/height < 0.95) {
      let treePosNoise = random(0.1, 0.9);
      let treePosX = lerp(0, width, treePosNoise);
      let treeCount = floor(random(60, 120));
      let treeSize = random(10, 30);
      drawTree(treePosX, yPos, treeSize, treeCount, random(-30, 30));
    }

    await sleep(10);
  }

  // drawGrass(300, 400, 6, 20, 0);
  // drawTree(300, 400, 30, 60, 0);

}

function drawGrass(_x, _y, _size, _drawCount, _startAngle) {

  var xPos = _x;
  var yPos = _y;
  let nowSize = _size;
  let nowAngle = _startAngle;


  let fromBri = 20;
  let toBri = 140;

  let nowBri = fromBri;

  if (isDarkGrass) {
    fromBri = 60;
    toBri = 6;
  }

  let nowHue = mainHue;

  for (let i = 0; i < _drawCount; i++) {
    let t = i / _drawCount;

    let sizeT = 1 - t;

    nowSize = lerp(2, _size, sizeT);

    let processedAngle = floor(nowAngle / grassAngleThreshold) * grassAngleThreshold;
    xPos += sin(radians(processedAngle)) * nowSize * 0.8;
    yPos -= cos(radians(processedAngle)) * nowSize * 0.8;
    let grassSat = random(10, 60);

    if (isWhiteGrass)
      grassSat = 0;


    fill(nowHue, grassSat, nowBri);
    stroke(0);

    push();
    translate(xPos, yPos);
    rotate(radians(processedAngle));
    rect(-0.5 * nowSize, -0.5 * nowSize, nowSize, nowSize);
    pop();

    nowAngle += noise(xPos * 0.01, yPos * 0.01) * 30 - 15;
    nowBri = lerp(fromBri, toBri, t);
    nowHue = (nowHue + 6) % 360;
  }
}

function drawTree(_x, _y, _size, _drawCount, _startAngle, _fromBri = 20) {
  var xPos = _x;
  var yPos = _y;
  var nowSize = _size;
  var nowAngle = _startAngle;

  var nowBri = _fromBri;

  let doSplit = false;
  let splitPos = random(0.05, 0.6);

  if (random() < 0.6)
    doSplit = true;

  if (_drawCount < 40)
    doSplit = false;

  for (let i = 0; i < _drawCount; i++) {
    var t = i / _drawCount;

    var sizeT = 1 - t;

    var processedAngle = floor(nowAngle / treeAngleThreshold) * treeAngleThreshold;
    nowSize = lerp(2, _size, sizeT);
    xPos += sin(radians(processedAngle)) * nowSize * 0.4;
    yPos -= cos(radians(processedAngle)) * nowSize * 0.4;

    let treeHue = mainHue + random(-30, 30);
    let treeSat = random(40, 60);
    let treeBri = random(90, 100);

    if (random() < 0.12)
      treeHue -= 60;

    if (treeHue > 360)
      treeHue -= 360;
    else if (treeHue < 0)
      treeHue += 360;

    if (random() < 0.06) {
      treeSat = 0;
      treeBri = 100;
    }

    if (isWhiteWood)
      treeSat = 0;
    // fill(treeHue, treeSat, nowBri);
    fill(treeHue, treeSat, treeBri);
    stroke('black');
    strokeWeight(1);
    // stroke('white');

    push();
    translate(xPos, yPos);
    rotate(radians(processedAngle));
    rect(-0.5 * nowSize, -0.5 * nowSize, nowSize, nowSize);
    pop();

    if (t > 0.4) {
      if (random() < 0.4) {
        let leafX = xPos + random(-60, 60);
        let leafY = yPos + random(-60, 60);
        let leafSize = nowSize * random(3, 6);

        NYCircle(leafX, leafY, leafSize);
      }
    }

    nowAngle += noise(xPos * 0.01, yPos * 0.003) * 10 - 5;
    nowBri = lerp(_fromBri, 140, t);

    if (doSplit && t > splitPos) {
      drawTree(xPos, yPos, nowSize, _drawCount - i, nowAngle + random(-30, -10), nowBri);
      drawTree(xPos, yPos, nowSize, _drawCount - i, nowAngle + random(10, 30), nowBri);

      break;
    }
  }
}

function NYCircle(_x, _y, _size) {

  let hueA = mainHue + random(-30, 30);
  let satA = random(10, 40);
  let briA = random(10, 40);


  let hueB = mainHue + random(-30, 30) + 180;
  let satB = random(10, 40);
  let briB = random(10, 40);


  if (hueA > 360)
    hueA -= 360;
  else if (hueA < 0)
    hueA += 360;

  if (hueB > 360)
    hueB -= 360;
  else if (hueB < 0)
    hueB += 360;

  for (let i = 0; i < _size; i += 8) {

    var nowHue = mainHue + random(-30, 30);
    if (random() < 0.2)
      nowHue += 180;

    if (nowHue > 360)
      nowHue -= 360;
    else if (nowHue < 0)
      nowHue += 360;


    let nowSat = random(10, 40);
    var nowBri = random(80, 100);

    stroke(nowHue, nowSat, nowBri);

    noFill();
    strokeWeight(1.5);

    var nowSize = _size - i;
    circle(_x, _y, nowSize);
  }
}

function draw() {

}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function keyPressed(e) {
  if (e.key == 's') {
    saveCanvas('hahow-tree-' + fxhash + '.png');
  }
}

